import { getNoteDuration } from 'app/services/MelodiesService/timing';
import { NoteInMelody } from 'app/services/MelodiesService/types';

import { LOOK_AHEAD } from './game';

const TAIL_LENGTH_SCALE = 4;

export const getKeyboardLookAhead = (
  speed: number,
  distance: number,
  keyBottom: number,
) =>
  LOOK_AHEAD * speed * (distance > 0 ? Math.max(1, keyBottom / distance) : 1);

// Times are in melody milliseconds; distance and targetTop are CSS pixels.
// All rows travel at the same rate and arrive at their actual key's rectangle.
export const getKeyboardNoteMotion = (
  note: NoteInMelody,
  elapsed: number,
  speed: number,
  targetTop: number,
  distance: number,
) => {
  const end = note.start + getNoteDuration(note);
  const pixelsPerMs = distance / (LOOK_AHEAD * speed);
  return {
    top: targetTop - Math.max(0, note.start - elapsed) * pixelsPerMs,
    // Magnify the remaining duration without changing the head's arrival time.
    tailHeight:
      Math.max(0, end - Math.max(note.start, elapsed)) *
      pixelsPerMs *
      TAIL_LENGTH_SCALE,
    sustaining: elapsed >= note.start && elapsed < end,
  };
};
