import { optimizeMelodyScale } from '../scaleOptimization';
import { Melody } from '../types';
import { openCollection } from './open';

export const builtInMelodies: Melody[] =
  openCollection.map(optimizeMelodyScale);

// Scan an existing directory so a fresh clone works without the ignored pack.
// Webpack drops this branch, and all private scores, from production builds.
const localMelodies: Melody[] = [];
if (process.env.NODE_ENV === 'development') {
  const context = require.context('./', true, /^\.\/local\/index\.ts$/);
  context.keys().forEach(key => localMelodies.push(...context(key).default));
}

export const melodies: Melody[] = [
  ...builtInMelodies,
  ...localMelodies.map(optimizeMelodyScale),
];
