import { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import styled from 'styled-components';

import { scaleLabels } from 'app/services/MelodiesService/scaleOptimization';
import { Octave, pitchNote, splitNote } from 'app/services/NotesService';
import { getNoteBindings } from 'app/services/PlayAlongService/game';
import {
  Mode,
  selectSettings,
  settingsActions,
} from 'app/services/SettingsService';
import { microtonalPreset } from 'app/services/SettingsService/microtonal';
import { fixedNotesFor } from 'app/services/SynthesizerService/timbres';

import { getTimbrePresentation } from 'app/components/TimbrePicker/catalog';

const modeLabels: Partial<Record<Mode, string>> = {
  ionian: 'Ионийский (мажор)',
  dorian: 'Дорийский',
  phrygian: 'Фригийский',
  lydian: 'Лидийский',
  mixolydian: 'Миксолидийский',
  aeolian: 'Эолийский (минор)',
  locrian: 'Локрийский',
  chromatic: 'Хроматический',
  custom: 'Ноты композиции',
  solo: '11 ступеней',
  h1: 'Гармонический минор',
  j1: 'Мелодический минор',
  p1: 'Мажорная пентатоника',
  p5: 'Минорная пентатоника',
};

export const SessionSettings = () => {
  const dispatch = useDispatch();
  const settings = useSelector(selectSettings);
  const { octave, pitch, scale, mode, timbre } = settings;
  const fixedNotes = fixedNotesFor(timbre);
  const tonic = splitNote(pitchNote('C4', pitch))[0];
  const canShift = (direction: number) => {
    const next = octave + direction;
    return (
      !fixedNotes &&
      next >= 0 &&
      next <= 8 &&
      Array.from(
        getNoteBindings({ ...settings, octave: next as Octave }).keys(),
      ).every(note => /^[A-G]#?[0-8]$/.test(note))
    );
  };
  const canLower = canShift(-1);
  const canRaise = canShift(1);

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (
        event.repeat ||
        event.metaKey ||
        event.ctrlKey ||
        event.altKey ||
        (event.target instanceof HTMLElement &&
          event.target.closest(
            'input, select, textarea, [contenteditable="true"], [data-session-control]',
          ))
      )
        return;
      const direction =
        event.code === 'ArrowDown' ? -1 : event.code === 'ArrowUp' ? 1 : 0;
      if (!direction) return;
      event.preventDefault();
      if (direction < 0 ? canLower : canRaise)
        dispatch(settingsActions.setOctave((octave + direction) as Octave));
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [canLower, canRaise, dispatch, octave]);

  return (
    <Bar aria-label="Текущие настройки">
      {!fixedNotes && (
        <OctaveControl aria-label="Управление октавой">
          <span>Октава</span>
          <button
            type="button"
            aria-label="На октаву ниже"
            aria-keyshortcuts="ArrowDown"
            title="На октаву ниже (↓)"
            disabled={!canLower}
            onClick={() =>
              dispatch(settingsActions.setOctave((octave - 1) as Octave))
            }
          >
            −
          </button>
          <strong aria-label="Текущая октава">{octave + 1}</strong>
          <button
            type="button"
            aria-label="На октаву выше"
            aria-keyshortcuts="ArrowUp"
            title="На октаву выше (↑)"
            disabled={!canRaise}
            onClick={() =>
              dispatch(settingsActions.setOctave((octave + 1) as Octave))
            }
          >
            +
          </button>
        </OctaveControl>
      )}
      <Details>
        {fixedNotes ? (
          <div>
            <dt>Строй</dt>
            <dd>Ре минор · {fixedNotes.join(', ')}</dd>
          </div>
        ) : (
          <>
            <div>
              <dt>Тональность</dt>
              <dd>
                {tonic} ·{' '}
                {microtonalPreset(scale, mode)?.label ??
                  (modeLabels[mode] || mode.toUpperCase())}
              </dd>
            </div>
            <div>
              <dt>Гамма</dt>
              <dd>{scaleLabels[scale]}</dd>
            </div>
          </>
        )}
        <div>
          <dt>Тембр</dt>
          <dd>{getTimbrePresentation(timbre).label}</dd>
        </div>
        {!fixedNotes && (
          <div title="Смещение в полутонах">
            <dt>Транспозиция</dt>
            <dd>
              {pitch > 0 ? '+' : ''}
              {pitch} пт
            </dd>
          </div>
        )}
      </Details>
    </Bar>
  );
};

const Bar = styled.section`
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 18px;
  overflow-x: auto;
  padding: 3px;
  scrollbar-width: thin;
  white-space: nowrap;
  min-width: 0;
  font-size: 11px;
  line-height: 1.3;
`;
const OctaveControl = styled.div`
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 5px;
  color: ${p => p.theme.textSecondary};
  button {
    width: 28px;
    height: 28px;
    min-height: 0;
    padding: 0;
    border: 1px solid ${p => p.theme.border};
    border-radius: 6px;
    color: ${p => p.theme.text};
    background: transparent;
    font-size: 16px;
    &:disabled {
      opacity: 0.4;
      cursor: default;
    }
    &:focus-visible {
      outline: 2px solid ${p => p.theme.primary};
      outline-offset: 2px;
    }
  }
  strong {
    min-width: 16px;
    text-align: center;
    color: ${p => p.theme.text};
    font-variant-numeric: tabular-nums;
    font-weight: 500;
  }
`;
const Details = styled.dl`
  display: flex;
  flex-shrink: 0;
  align-items: baseline;
  gap: 4px 16px;
  min-width: 0;
  margin: 0;
  div {
    display: flex;
    gap: 3px;
    min-width: 0;
  }
  dt {
    color: ${p => p.theme.textSecondary};
  }
  dd {
    margin: 0;
    color: ${p => p.theme.text};
  }
  @media (max-width: 600px) {
    gap: 4px 10px;
    font-size: 10px;
  }
  @media (max-height: 480px) {
    font-size: 10px;
    gap: 3px 10px;
  }
`;
