import { PayloadAction } from '@reduxjs/toolkit';

import { Melody, NoteInMelody } from 'app/services/MelodiesService';
import {
  NormalizationOptions,
  normalizeMelody,
} from 'app/services/MelodiesService/normalization';
import { MelodyScaleSettings } from 'app/services/MelodiesService/scaleOptimization';
import { getNoteDuration } from 'app/services/MelodiesService/timing';
import {
  settingsActions,
  initialState as settingsInitialState,
} from 'app/services/SettingsService/slice';
import { Timbre, muteNote } from 'app/services/SynthesizerService';

import { createSlice, useInjectReducer } from 'utils';

import { playLiveNote } from '../livePlayback';
import { Note } from '../types';
import { NotesState } from './types';

type GuitarNoteUpdate = {
  version: number;
  id: number;
  startedAt: number;
  note: NoteInMelody;
};

const mergeGuitarNote = (state: NotesState, payload: GuitarNoteUpdate) => {
  if (
    payload.version !== state.recordingVersion ||
    state.melodyBeforeNormalization
  )
    return;
  const indices = (state.liveGuitarNotes ??= {});
  const index = indices[payload.id];
  if (index !== undefined) {
    const note = state.melody.notes[index];
    if (note?.note === payload.note.note) {
      note.duration = payload.note.duration;
      note.expression = payload.note.expression;
    }
    return;
  }
  const absoluteStart = payload.startedAt + payload.note.start;
  const previousStart = state.melody.firstStart ?? absoluteStart;
  const firstStart = Math.min(previousStart, absoluteStart);
  state.melody.notes.forEach(note => {
    note.start += previousStart - firstStart;
  });
  state.melody.firstStart = firstStart;
  indices[payload.id] = state.melody.notes.length;
  state.melody.notes.push({
    ...payload.note,
    start: absoluteStart - firstStart,
  });
  state.melodyBeforeNormalization = undefined;
};

export const initialState: NotesState = {
  soundingNotes: [],
  noteInputs: {},
  recordingVersion: 0,
  liveAudioNotes: [],
  highlightedNotes: [],
  melody: {
    title: '',
    scale: settingsInitialState.scale,
    mode: settingsInitialState.mode,
    pitch: settingsInitialState.pitch,
    octave: settingsInitialState.octave,
    timbre: settingsInitialState.timbre,
    bpm: settingsInitialState.bpm,
    timeSignature: settingsInitialState.timeSignature,
    notes: [],
  },
};

const slice = createSlice({
  name: 'notes',
  initialState,
  reducers: {
    // play
    playNote(
      state,
      {
        payload,
      }: PayloadAction<{
        timbre: Timbre;
        note: Note;
        source?: string;
        tuningCents?: number;
      }>,
    ) {
      const { note, timbre, source = 'local', tuningCents = 0 } = payload;
      const input = state.noteInputs[note];
      if (input) {
        if (!input.sources.includes(source)) input.sources.push(source);
        return;
      }
      playLiveNote(timbre, note, tuningCents);
      state.noteInputs[note] = {
        timbre,
        sources: [source],
        ...(tuningCents ? { tuningCents } : {}),
      };
      state.soundingNotes.push(note);
    },
    muteNote(
      state,
      {
        payload,
      }: PayloadAction<{
        timbre: Timbre;
        note: Note;
        source?: string;
        allSources?: boolean;
      }>,
    ) {
      const { note, source = 'local', allSources } = payload;
      if (!state.soundingNotes.includes(note)) return;
      const input = state.noteInputs[note];
      if (input && !allSources) {
        input.sources = input.sources.filter(owner => owner !== source);
        if (input.sources.length) return;
      }
      muteNote(input?.timbre ?? payload.timbre, note);
      delete state.noteInputs[note];
      state.soundingNotes = state.soundingNotes.filter(n => n !== note);
    },

    // highlight
    highlightNote(state, action: PayloadAction<Note>) {
      if (state.highlightedNotes.includes(action.payload)) {
        return;
      }
      state.highlightedNotes.push(action.payload);
    },
    playdownNote(state, action: PayloadAction<Note>) {
      if (!state.highlightedNotes.includes(action.payload)) {
        return;
      }
      state.highlightedNotes = state.highlightedNotes.filter(
        note => note !== action.payload,
      );
    },
    playdownAllNotes(state, action: PayloadAction<void>) {
      state.highlightedNotes = [];
    },

    // melody
    startRecording(state, action: PayloadAction<Omit<Melody, 'notes'>>) {
      state.recordingVersion++;
      state.liveGuitarNotes = undefined;
      state.liveAudioNotes = [];
      state.melody = { ...action.payload, notes: [] };
      state.melodyBeforeNormalization = undefined;
    },
    loadRecording(state, action: PayloadAction<Melody>) {
      state.recordingVersion++;
      state.liveGuitarNotes = undefined;
      state.liveAudioNotes = [];
      state.melody = {
        ...action.payload,
        firstStart: undefined,
        notes: action.payload.notes.map(note => ({
          ...note,
          duration: getNoteDuration(note),
        })),
      };
      state.melodyBeforeNormalization = undefined;
    },
    editRecording(
      state,
      action: PayloadAction<NoteInMelody[] | Pick<Melody, 'notes' | 'bpm'>>,
    ) {
      const patch = Array.isArray(action.payload)
        ? { notes: action.payload }
        : action.payload;
      if (state.melody.notes.some(note => note.duration === undefined)) return;
      state.melodyBeforeNormalization ??= state.melody;
      state.melody = { ...state.melody, ...patch };
    },
    setRecordingScale(state, action: PayloadAction<MelodyScaleSettings>) {
      if (state.melody.notes.some(note => note.duration === undefined)) return;
      const {
        scale,
        mode,
        pitch,
        octave,
        customScale,
        keyboardStart,
        keyboardLayout,
      } = action.payload;
      Object.assign(state.melody, {
        scale,
        mode,
        pitch,
        octave,
        customScale,
        keyboardStart,
        keyboardLayout,
      });
    },
    streamGuitarNote(state, { payload }: PayloadAction<GuitarNoteUpdate>) {
      mergeGuitarNote(state, payload);
    },
    refineGuitarRecording(
      state,
      { payload }: PayloadAction<{ version: number; notes: NoteInMelody[] }>,
    ) {
      if (
        payload.version !== state.recordingVersion ||
        state.melodyBeforeNormalization
      )
        return;
      const indices = new Set(Object.values(state.liveGuitarNotes ?? {}));
      state.melody.notes = [
        ...state.melody.notes.filter((_, index) => !indices.has(index)),
        ...payload.notes,
      ].sort((a, b) => a.start - b.start);
      state.liveGuitarNotes = undefined;
    },
    streamGuitarNotes(
      state,
      {
        payload,
      }: PayloadAction<{
        version: number;
        events: Omit<GuitarNoteUpdate, 'version'>[];
        soundingNotes: Note[];
      }>,
    ) {
      if (
        payload.version !== state.recordingVersion ||
        state.melodyBeforeNormalization
      )
        return;
      payload.events.forEach(event =>
        mergeGuitarNote(state, { ...event, version: payload.version }),
      );
      state.liveAudioNotes = Array.from(new Set(payload.soundingNotes));
    },
    addGuitarRecording(
      state,
      {
        payload,
      }: PayloadAction<{
        version: number;
        startedAt: number;
        notes: NoteInMelody[];
      }>,
    ) {
      if (payload.version !== state.recordingVersion || !payload.notes.length)
        return;
      const firstDetected =
        payload.startedAt + Math.min(...payload.notes.map(note => note.start));
      const previousStart = state.melody.firstStart ?? firstDetected;
      const firstStart = Math.min(previousStart, firstDetected);
      state.melody.notes.forEach(note => {
        note.start += previousStart - firstStart;
      });
      state.melody.firstStart = firstStart;
      state.melody.notes.push(
        ...payload.notes.map(note => ({
          ...note,
          start: payload.startedAt + note.start - firstStart,
        })),
      );
      state.melody.notes.sort((a, b) => a.start - b.start);
      state.melodyBeforeNormalization = undefined;
    },
    normalizeRecording(state, action: PayloadAction<NormalizationOptions>) {
      const result = normalizeMelody(state.melody, action.payload);
      if (!result.melody.notes.length) return;
      state.melodyBeforeNormalization ??= state.melody;
      state.melody = result.melody;
    },
    restoreRecording(state) {
      if (!state.melodyBeforeNormalization) return;
      state.melody = state.melodyBeforeNormalization;
      state.melodyBeforeNormalization = undefined;
    },
    finishRecording(state) {
      state.liveAudioNotes = [];
      const end = Date.now() - (state.melody.firstStart ?? Date.now());
      state.melody.notes.forEach(note => {
        if (note.duration === undefined) {
          note.duration = Math.max(1, end - note.start);
        }
      });
    },
    logStartingNote(state, action: PayloadAction<Note>) {
      if (
        state.melody.notes.some(
          note => note.note === action.payload && note.duration === undefined,
        )
      ) {
        return;
      }
      const start = Date.now();
      const cents = state.noteInputs[action.payload]?.tuningCents ?? 0;
      state.melody.firstStart ??= start;
      state.melody.notes.push({
        note: action.payload,
        start: start - state.melody.firstStart,
        ...(cents
          ? {
              expression: {
                points: [
                  { position: 0, cents },
                  { position: 1, cents },
                ],
                techniques: [],
              },
            }
          : {}),
      });
    },
    logEndingNote(state, action: PayloadAction<Note>) {
      if (state.soundingNotes.includes(action.payload)) return;
      const soundingNote = state.melody.notes.find(
        note => note.note === action.payload && note.duration === undefined,
      );
      if (!soundingNote || state.melody.firstStart === undefined) {
        return;
      }
      soundingNote.duration = Math.max(
        1,
        Date.now() - state.melody.firstStart - soundingNote.start,
      );
    },
  },
  extraReducers: builder => {
    builder.addCase(settingsActions.setTimeSignature, (state, action) => {
      state.melody.timeSignature = action.payload;
    });
  },
});

export const { actions: notesActions, reducer } = slice;

export const useNotesSlice = () => {
  useInjectReducer({ key: slice.name, reducer: slice.reducer });
  return { actions: slice.actions };
};
