import type { useGuitarInput } from 'app/services/GuitarInputService/useGuitarInput';

export const InputSoundControls = ({
  guitar,
}: {
  guitar: Pick<
    ReturnType<typeof useGuitarInput>,
    | 'inputSound'
    | 'inputPolyphonic'
    | 'setInputSound'
    | 'setInputPolyphonic'
    | 'inputTransferAmount'
    | 'setInputTransferAmount'
    | 'transferDelayMs'
  >;
}) => (
  <div>
    <label>
      Звук аудиовхода
      <select
        aria-label="Звук аудиовхода"
        value={guitar.inputSound ?? 'effects'}
        onChange={event =>
          guitar.setInputSound(event.target.value as typeof guitar.inputSound)
        }
      >
        <option value="effects">Исходный звук с эффектами</option>
        <option value="instrument">Выбранный тембр приложения</option>
        <option value="transfer">Петля тембра: бенды и динамика</option>
      </select>
    </label>
    {guitar.inputSound === 'instrument' && (
      <>
        <label>
          Игра тембром
          <select
            aria-label="Распознавание для выбранного тембра"
            value={guitar.inputPolyphonic ? 'poly' : 'mono'}
            onChange={event =>
              guitar.setInputPolyphonic(event.target.value === 'poly')
            }
          >
            <option value="mono">Одна нота: быстрее</option>
            <option value="poly">Ноты и аккорды</option>
          </select>
        </label>
        <p>
          Выберите пианино или другой тембр в верхней панели и включите живой
          звук. Играть можно без записи. Громкость и эффекты берутся у
          выбранного тембра; исходный звук входа не слышен.
        </p>
        <p>
          Распознавание добавляет задержку. Одиночные чистые ноты откликаются
          быстрее; аккорды требуют больше времени и могут распознаваться с
          ошибками. Используйте наушники, чтобы звук приложения не попадал
          обратно в микрофон.
        </p>
      </>
    )}
    {guitar.inputSound === 'transfer' && (
      <>
        <label>
          Доля петли: {guitar.inputTransferAmount}%
          <input
            type="range"
            aria-label="Доля петли тембра"
            min={0}
            max={100}
            step={1}
            value={guitar.inputTransferAmount}
            onChange={event =>
              guitar.setInputTransferAmount(Number(event.target.value))
            }
          />
        </label>
        <p>
          Ровный фрагмент выбранного тембра играет по кругу без затухания.
          Громкость входа управляет его огибающей, а непрерывная высота меняет
          скорость петли: бенды и вибрато без округления к нотам. При смене
          высоты петля не запускается заново.
        </p>
        <p>
          Для одной ноты: аккорды не разделяются. На 100% слышна петля, на 0%
          исходный вход, между ними смесь. Нужен тембр с устойчивым тоном; у
          шумовых и некоторых ударных петля может не получиться. Окно анализа{' '}
          {guitar.transferDelayMs} мс, обновление каждые 10 мс; полная задержка
          зависит от входа и устройства. Используйте наушники.
        </p>
      </>
    )}
  </div>
);
