import { useOutletContext } from 'react-router-dom';
import styled from 'styled-components';

import { getMelodyDuration } from 'app/services/MelodiesService/melodies';
import { Melody } from 'app/services/MelodiesService/types';
import { useMelodyPlayback } from 'app/services/MelodiesService/useMelodyPlayback';

type RecordingPlayback = ReturnType<typeof useMelodyPlayback>;

export const useRecordingPlayback = () =>
  useOutletContext<RecordingPlayback | undefined>();

const formatTime = (ms: number) =>
  `${Math.floor(ms / 60000)}:${((Math.floor(ms / 100) % 600) / 10)
    .toFixed(1)
    .padStart(4, '0')}`;

export const RecordingPlaybackPosition = ({
  melody,
  playback,
}: {
  melody: Melody;
  playback: RecordingPlayback;
}) => (
  <Position>
    <span>Позиция</span>
    <input
      type="range"
      aria-label="Позиция в записи"
      min={0}
      max={getMelodyDuration(melody)}
      step={1}
      value={Math.round(playback.position)}
      aria-valuetext={formatTime(playback.position)}
      onChange={event => playback.seek(Number(event.target.value))}
    />
    <span role="timer" aria-label="Время записи" aria-live="off">
      {formatTime(playback.position)} / {formatTime(getMelodyDuration(melody))}
    </span>
  </Position>
);

const Position = styled.div`
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 4px;
  color: ${p => p.theme.textSecondary};
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  input {
    flex: 1;
    min-width: 40px;
    accent-color: ${p => p.theme.primary};
    cursor: pointer;
  }
`;
