import { sampleRegion } from 'app/services/SynthesizerService/sampleLayout';
import { sampleDefinition } from 'app/services/SynthesizerService/timbres';
import { Timbre } from 'app/services/SynthesizerService/types';
import { detectPitch } from 'app/services/TunerService/pitch';

export const LOOP_ANALYSIS_MS = 48;
const TABLE_SIZE = 512;

// Average phase-aligned cycles from a steady section of the actual sample.
// This removes decay/vibrato from the carrier without a spectral envelope.
// Integer source indices belong to [ceil(start), ceil(end)); interpolation
// never reads the next sample slot at its excluded endpoint.
export const prepareTimbreLoop = (buffer: AudioBuffer, timbre: Timbre) => {
  const data = buffer.getChannelData(0);
  const rate = buffer.sampleRate;
  const definition = sampleDefinition(timbre);
  const indices = [36, 48, 45, 57];
  if (definition.pitchedNotes)
    indices.push(...definition.pitchedNotes.map(note => note.index));
  let best:
    | { start: number; end: number; frequency: number; score: number }
    | undefined;
  for (const index of Array.from(new Set(indices))) {
    const region = sampleRegion(
      index,
      definition,
      timbre === 'drums',
      buffer.duration,
    );
    if (!region) continue;
    const slotStart = Math.ceil(region.offset * rate);
    const slotEnd = Math.min(
      data.length,
      Math.ceil((region.offset + region.duration) * rate),
    );
    const low = Math.max(
      slotStart,
      Math.ceil((region.offset + (region.loop?.loopStart ?? 0.12)) * rate),
    );
    const high = Math.min(
      slotEnd,
      Math.ceil(
        (region.offset +
          (region.loop?.loopEnd ?? Math.min(region.duration, 1.2))) *
          rate,
      ),
    );
    const size = Math.round(rate * 0.16);
    if (high - low < size) continue;
    for (let step = 0; step < 6; step++) {
      const start = Math.round(low + ((high - low - size) * step) / 5);
      const frame = data.slice(start, start + size);
      const rms = Math.sqrt(
        frame.reduce((sum, value) => sum + value * value, 0) / size,
      );
      if (rms < 0.0005) continue;
      const normalized = Float32Array.from(frame, value => (value * 0.1) / rms);
      const frequency = detectPitch(normalized, rate, 2000);
      const first = detectPitch(
        normalized.slice(0, Math.floor(size / 2)),
        rate,
        2000,
      );
      const last = detectPitch(
        normalized.slice(Math.floor(size / 2)),
        rate,
        2000,
      );
      if (!frequency || !first || !last) continue;
      const drift = Math.abs(1200 * Math.log2(first / last));
      const expected =
        (440 * 2 ** ((index + 12 - 69) / 12)) / region.playbackRate;
      if (
        drift > 35 ||
        (region.expressive &&
          Math.abs(1200 * Math.log2(frequency / expected)) > 100)
      )
        continue;
      const score = drift + step * 0.1;
      if (!best || score < best.score)
        best = { start, end: start + size, frequency, score };
    }
    // Prefer the first usable register; later registers are fallbacks.
    if (best) break;
  }
  if (!best)
    throw new Error(
      'В этом тембре не найден ровный тон для петли. Попробуйте пианино, орган или флейту.',
    );
  const period = rate / best.frequency;
  const cycles = Math.min(16, Math.floor((best.end - best.start - 1) / period));
  if (cycles < 4)
    throw new Error('Устойчивый фрагмент тембра слишком короткий для петли.');
  const table = new Float32Array(TABLE_SIZE);
  const cycle = new Float32Array(TABLE_SIZE);
  for (let c = 0; c < cycles; c++) {
    let mean = 0,
      energy = 0;
    for (let i = 0; i < TABLE_SIZE; i++) {
      const position = best.start + (c + i / TABLE_SIZE) * period;
      const left = Math.floor(position);
      const right = Math.min(best.end - 1, left + 1);
      const value = data[left] + (data[right] - data[left]) * (position - left);
      cycle[i] = value;
      mean += value / TABLE_SIZE;
    }
    cycle.forEach(value => {
      energy += (value - mean) ** 2;
    });
    const rms = Math.sqrt(energy / TABLE_SIZE);
    if (rms < 1e-6) continue;
    for (let i = 0; i < TABLE_SIZE; i++)
      table[i] += (cycle[i] - mean) / rms / cycles;
  }
  const rms = Math.sqrt(
    table.reduce((sum, value) => sum + value * value, 0) / TABLE_SIZE,
  );
  if (rms < 0.01)
    throw new Error(
      'Не удалось подготовить устойчивую петлю выбранного тембра.',
    );
  for (let i = 0; i < TABLE_SIZE; i++) table[i] /= rms;
  return table;
};
