import { useCallback, useEffect, useRef, useState } from 'react';
import { useDispatch } from 'react-redux';

import {
  effectsActions,
  useEffectsSlice,
} from 'app/services/EffectsService/slice';
import { resumeAudio } from 'app/services/SynthesizerService';

import { cropExpression } from './expression';
import { getMelodyDuration, playMelody, stopMelody } from './melodies';
import { melodiesActions } from './slice';
import { estimateTempo } from './tempo';
import { DEFAULT_BPM, getNoteDuration } from './timing';
import { Melody } from './types';

export const getPlaybackTail = (melody: Melody, position: number) =>
  melody.notes
    .map((note, index) => ({ note, index }))
    .filter(({ note }) => note.start + getNoteDuration(note) > position)
    .map(({ note, index }) => ({
      index,
      note: {
        ...note,
        start: Math.max(0, note.start - position),
        duration:
          note.start + getNoteDuration(note) - Math.max(position, note.start),
        ...(note.expression
          ? {
              expression: cropExpression(
                note.expression,
                Math.max(0, position - note.start) / getNoteDuration(note),
              ),
            }
          : {}),
      },
    }));

type Kind = 'timeline' | 'preview' | 'audition';
type Session = {
  piece: Melody;
  offset: number;
  at: number;
  kind: Kind;
  noteIndex?: number;
};
const boundedPosition = (piece: Melody, position: number) =>
  Math.max(
    0,
    Math.min(
      getMelodyDuration(piece),
      Number.isFinite(position) ? position : 0,
    ),
  );
const elapsed = (session: Session) =>
  boundedPosition(
    session.piece,
    session.offset + performance.now() - session.at,
  );
const retimedPosition = (previous: Melody, next: Melody, position: number) => {
  const referenceBpm =
    previous.bpm ?? estimateTempo(previous.notes)?.bpm ?? DEFAULT_BPM;
  const ratio = referenceBpm / (next.bpm ?? referenceBpm);
  const retimed =
    previous.notes !== next.notes &&
    previous.notes.length === next.notes.length &&
    next.notes.every((note, index) => {
      const original = previous.notes[index];
      return (
        note.note === original.note &&
        Math.abs(note.start - original.start * ratio) <= 1 &&
        Math.abs(getNoteDuration(note) - getNoteDuration(original) * ratio) <= 1
      );
    });
  return boundedPosition(next, position * (retimed ? ratio : 1));
};

/** One monotonic clock for sound, pause, scrubbing and live edits. Pausing
 * releases voices and cancels pending attacks; resuming only schedules [cursor, end).
 * Auditioning a note keeps the paused melody's bookmark intact. */
export const useMelodyPlayback = (melody: Melody | undefined) => {
  useEffectsSlice();
  const dispatch = useDispatch();
  const [isPlaying, setPlaying] = useState(false);
  const [isPaused, setPaused] = useState(false);
  const [position, setPosition] = useState(0);
  const [isAudition, setAudition] = useState(false);
  const [timelineVisible, setTimelineVisible] = useState(false);
  const cursor = useRef(0);
  const active = useRef<Session | null>(null);
  const paused = useRef<Session | null>(null);
  const previousMelody = useRef(melody);
  const moveCursor = useCallback((time: number) => {
    cursor.current = time;
    setPosition(time);
  }, []);
  const stop = useCallback(() => {
    active.current = null;
    paused.current = null;
    stopMelody();
    setPlaying(false);
    setPaused(false);
    setAudition(false);
    setTimelineVisible(false);
    moveCursor(0);
    dispatch(melodiesActions.resetPlayback());
  }, [dispatch, moveCursor]);
  const unlock = useCallback(() => {
    Promise.resolve(resumeAudio?.()).catch(stop);
  }, [stop]);
  const schedule = useCallback(
    (piece: Melody, time: number, kind: Kind, noteIndex?: number) => {
      stopMelody();
      dispatch(
        effectsActions.activateMelody({
          context: `library:${piece.title}`,
          timbre: piece.timbre,
          preset: piece.effectPreset,
        }),
      );
      dispatch(melodiesActions.resetPlayback());
      const offset = boundedPosition(piece, time);
      const session: Session = {
        piece,
        offset,
        at: performance.now(),
        kind,
        noteIndex,
      };
      active.current = session;
      setPlaying(true);
      setAudition(kind === 'audition');
      if (kind !== 'audition') {
        paused.current = null;
        setPaused(false);
        setTimelineVisible(kind === 'timeline');
        moveCursor(offset);
      }
      const tail = getPlaybackTail(piece, offset);
      playMelody(
        { ...piece, notes: tail.map(event => event.note) },
        {
          onNotePlayed: index =>
            dispatch(
              melodiesActions.setCurrentNoteIndex(
                noteIndex ?? tail[+index].index,
              ),
            ),
          onNoteMuted: index =>
            dispatch(
              melodiesActions.muteNoteIndex(noteIndex ?? tail[+index].index),
            ),
          onMelodyEnded: () => {
            if (active.current !== session) return;
            active.current = null;
            setPlaying(false);
            setAudition(false);
            if (kind === 'audition') {
              setPaused(!!paused.current);
              return;
            }
            paused.current = null;
            setPaused(false);
            moveCursor(getMelodyDuration(piece));
          },
        },
      );
    },
    [dispatch, moveCursor],
  );
  const pause = useCallback(() => {
    const session = active.current;
    if (!session) return;
    active.current = null;
    if (session.kind !== 'audition') {
      const time = elapsed(session);
      paused.current = { ...session, offset: time };
      moveCursor(time);
    }
    stopMelody();
    setPlaying(false);
    setAudition(false);
    setPaused(!!paused.current);
    dispatch(melodiesActions.resetPlayback());
  }, [dispatch, moveCursor]);
  const play = useCallback(
    (piece: Melody = melody!, noteIndex?: number) => {
      if (!piece?.notes.length) return;
      unlock();
      if (noteIndex !== undefined) {
        pause();
        schedule(piece, 0, 'audition', noteIndex);
      } else {
        const kind = piece.notes === melody?.notes ? 'timeline' : 'preview';
        const offset =
          kind === 'timeline' && cursor.current < getMelodyDuration(piece)
            ? cursor.current
            : 0;
        schedule(piece, offset, kind);
      }
    },
    [melody, pause, schedule, unlock],
  );
  const resume = useCallback(() => {
    const saved = paused.current;
    unlock();
    if (saved)
      schedule(
        saved.kind === 'timeline' && melody ? melody : saved.piece,
        saved.offset,
        saved.kind,
        saved.noteIndex,
      );
    else if (melody?.notes.length)
      schedule(
        melody,
        cursor.current < getMelodyDuration(melody) ? cursor.current : 0,
        'timeline',
      );
  }, [melody, schedule, unlock]);
  const seek = useCallback(
    (time: number) => {
      if (!melody) return;
      const target = boundedPosition(melody, time);
      if (active.current?.kind === 'timeline') {
        schedule(melody, target, 'timeline');
        return;
      }
      active.current = null;
      stopMelody();
      setPlaying(false);
      setAudition(false);
      dispatch(melodiesActions.resetPlayback());
      if (paused.current)
        paused.current = {
          piece: melody,
          offset: target,
          at: performance.now(),
          kind: 'timeline',
        };
      setPaused(!!paused.current);
      setTimelineVisible(true);
      moveCursor(target);
    },
    [dispatch, melody, moveCursor, schedule],
  );
  useEffect(() => {
    const previous = previousMelody.current;
    previousMelody.current = melody;
    if (!melody || !previous || previous === melody) return;
    const session = active.current;
    if (session?.kind === 'audition' && previous.notes !== melody.notes)
      pause();
    if (session?.kind === 'timeline') {
      schedule(
        melody,
        retimedPosition(session.piece, melody, elapsed(session)),
        'timeline',
      );
    } else if (paused.current?.kind === 'timeline') {
      const saved = paused.current;
      const time = retimedPosition(saved.piece, melody, saved.offset);
      paused.current = { ...saved, piece: melody, offset: time };
      moveCursor(time);
    } else if (!session || session.kind === 'audition')
      moveCursor(retimedPosition(previous, melody, cursor.current));
  }, [melody, moveCursor, pause, schedule]);
  useEffect(() => {
    if (!isPlaying) return;
    const timer = window.setInterval(() => {
      const session = active.current;
      if (session && session.kind !== 'audition') moveCursor(elapsed(session));
    }, 40);
    return () => window.clearInterval(timer);
  }, [isPlaying, moveCursor]);
  useEffect(
    () => () => {
      active.current = null;
      paused.current = null;
      stopMelody();
    },
    [],
  );
  return {
    isPlaying,
    isPaused,
    isAudition,
    position,
    timelinePlaying: timelineVisible,
    play,
    pause,
    resume,
    seek,
    stop,
  };
};
