import { dissoc } from 'ramda';
import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { batch, useDispatch, useSelector } from 'react-redux';
import { Link, Outlet, useLocation, useMatch } from 'react-router-dom';
import styled from 'styled-components';

import { useConnectedGuitarInput } from 'app/services/GuitarInputService/context';
import { DEFAULT_TIME_SIGNATURE } from 'app/services/MelodiesService/meter';
import { normalizeMelody } from 'app/services/MelodiesService/normalization';
import {
  getMelodyBpm,
  useActivateMelody,
  useCurrentMelody,
} from 'app/services/MelodiesService/useCurrentMelody';
import { useMelodyPlayback } from 'app/services/MelodiesService/useMelodyPlayback';
import { notesActions, selectNotes } from 'app/services/NotesService';
import { selectSettings, settingsActions } from 'app/services/SettingsService';

import { InputDevicesSlot } from 'app/components/InputDevices';
import { LiveAudioRecognition } from 'app/components/LiveAudioRecognition';
import {
  MelodyActionButton,
  MelodyActionIcon,
} from 'app/components/MelodyAction';
import { MelodyEditorIcon } from 'app/components/MelodyEditorAction';
import { MelodyExport } from 'app/components/MelodyExport';
import { MelodyImport } from 'app/components/MelodyImport';
import { MelodyScaleOptimization } from 'app/components/MelodyScaleOptimization';
import { RecordingEditor } from 'app/components/RecordingEditor';
import { RecordingNormalization } from 'app/components/RecordingNormalization';
import { RecordingPlaybackPosition } from 'app/components/RecordingPlayback';
import { SandboxInstrument } from 'app/components/SandboxInstrument';
import { SandboxViews } from 'app/components/SandboxViews';
import { PageWrapper } from 'app/components/_styled/PageWrapper';

export const SandboxPage = () => {
  const guitar = useConnectedGuitarInput();
  const dispatch = useDispatch();
  const location = useLocation();
  const flyingNotes = useMatch('/sandbox/flying-notes');
  const toolbar = useRef<HTMLDivElement>(null);
  const [editorOpen, setEditorOpen] = useState(
    () =>
      !!(location.state as { editRecording?: boolean } | null)?.editRecording,
  );
  const [actionDetails, setActionDetails] = useState<HTMLDivElement | null>(
    null,
  );
  const {
    octave,
    pitch,
    scale,
    mode,
    customScale,
    timbre,
    bpm,
    timeSignature = DEFAULT_TIME_SIGNATURE,
    isRecording,
  } = useSelector(selectSettings);
  const {
    melody: source,
    melodyBeforeNormalization,
    recordingVersion,
  } = useSelector(selectNotes);
  useActivateMelody(source, 'recording', false);
  const melody = useCurrentMelody(source)!;
  const playback = useMelodyPlayback(melody);
  const { isPlaying, play: startPlayback, stop: stopPlayback } = playback;
  const recordingRef = useRef(isRecording);
  recordingRef.current = isRecording;

  useLayoutEffect(() => {
    const element = toolbar.current;
    const container = element?.parentElement;
    if (!element || !container) return;
    const measure = () =>
      container.style.setProperty(
        '--sandbox-toolbar-height',
        `${element.getBoundingClientRect().height}px`,
      );
    measure();
    const observer =
      typeof ResizeObserver === 'undefined'
        ? null
        : new ResizeObserver(measure);
    observer?.observe(element);
    window.addEventListener('resize', measure);
    return () => {
      observer?.disconnect();
      window.removeEventListener('resize', measure);
      container.style.removeProperty('--sandbox-toolbar-height');
    };
  }, []);

  useEffect(
    () => () => {
      if (recordingRef.current) {
        dispatch(notesActions.finishRecording());
        dispatch(settingsActions.toggleRecording());
      }
    },
    [dispatch],
  );

  return (
    <SandboxWrapper>
      <SandboxToolbar ref={toolbar}>
        <RecordingBar aria-label="Управление записью">
          <InputDevicesSlot />
          <ControlGroup role="group" aria-label="Запись">
            <GroupLabel aria-hidden="true">Запись</GroupLabel>
            <GroupActions>
              <RecordButton
                $withLabel
                type="button"
                aria-label={isRecording ? 'Остановить запись' : 'Записать'}
                title={isRecording ? 'Остановить запись' : 'Новая запись'}
                aria-pressed={isRecording}
                onClick={() => {
                  stopPlayback();
                  batch(() => {
                    if (isRecording) {
                      dispatch(notesActions.finishRecording());
                    } else {
                      dispatch(
                        notesActions.startRecording({
                          title: '',
                          scale,
                          mode,
                          customScale,
                          pitch,
                          octave,
                          timbre,
                          bpm,
                          timeSignature,
                        }),
                      );
                    }
                    dispatch(settingsActions.toggleRecording());
                  });
                }}
              >
                <MelodyActionIcon action={isRecording ? 'stop' : 'record'} />
                {isRecording ? 'Остановить запись' : 'Записать'}
              </RecordButton>
              {!!melody.notes.length && !isRecording && (
                <>
                  <MelodyActionButton
                    $withLabel
                    type="button"
                    aria-label={
                      isPlaying
                        ? 'Остановить воспроизведение'
                        : playback.isPaused
                        ? 'Продолжить'
                        : 'Слушать'
                    }
                    title={
                      isPlaying
                        ? 'Остановить воспроизведение'
                        : 'Воспроизвести запись'
                    }
                    onClick={() => {
                      if (isPlaying) {
                        stopPlayback();
                        return;
                      }
                      if (playback.isPaused) playback.resume();
                      else startPlayback(melody);
                    }}
                  >
                    <MelodyActionIcon action={isPlaying ? 'stop' : 'play'} />
                    {isPlaying
                      ? 'Остановить воспроизведение'
                      : playback.isPaused
                      ? 'Продолжить'
                      : 'Слушать'}
                  </MelodyActionButton>
                  {isPlaying && !playback.isAudition && (
                    <MelodyActionButton
                      $withLabel
                      type="button"
                      aria-label="Пауза воспроизведения"
                      title="Приостановить воспроизведение"
                      onClick={playback.pause}
                    >
                      <MelodyEditorIcon icon="pause" />
                      Пауза
                    </MelodyActionButton>
                  )}
                  <MelodyActionButton
                    $withLabel
                    as={Link}
                    to="/play-along/recording"
                    aria-label="Играть вместе"
                    title="Играть вместе с записью"
                  >
                    <MelodyActionIcon action="practice" />
                    Играть вместе
                  </MelodyActionButton>
                </>
              )}
            </GroupActions>
          </ControlGroup>
          {!isRecording && (
            <ControlGroup role="group" aria-label="Правка">
              <GroupLabel aria-hidden="true">Правка</GroupLabel>
              <GroupActions>
                <MelodyActionButton
                  $withLabel
                  type="button"
                  aria-label={
                    editorOpen ? 'Скрыть редактор' : 'Редактировать мелодию'
                  }
                  title={
                    editorOpen ? 'Скрыть редактор' : 'Редактировать мелодию'
                  }
                  aria-expanded={editorOpen}
                  onClick={() => {
                    setEditorOpen(!editorOpen);
                  }}
                >
                  <MelodyActionIcon action={editorOpen ? 'close' : 'edit'} />
                  {editorOpen ? 'Скрыть редактор' : 'Редактировать'}
                </MelodyActionButton>

                {!!melody.notes.length && (
                  <RecordingNormalization
                    compact
                    showLabel
                    key={melody.firstStart}
                    melody={melody}
                    canRestore={!!melodyBeforeNormalization}
                    isPlaying={isPlaying}
                    onStop={stopPlayback}
                    onPreview={startPlayback}
                    onApply={options => {
                      stopPlayback();
                      const result = normalizeMelody(melody, options).melody;
                      if (!result.notes.length) return;
                      batch(() => {
                        dispatch(
                          notesActions.editRecording({
                            notes: result.notes,
                            bpm: result.bpm,
                          }),
                        );
                        dispatch(settingsActions.setBpm(result.bpm!));
                      });
                    }}
                    onRestore={() => {
                      stopPlayback();
                      dispatch(notesActions.restoreRecording());
                      if (melodyBeforeNormalization)
                        dispatch(
                          settingsActions.setBpm(
                            getMelodyBpm(melodyBeforeNormalization),
                          ),
                        );
                    }}
                  />
                )}
              </GroupActions>
            </ControlGroup>
          )}
          <ControlGroup role="group" aria-label="Файлы">
            <GroupLabel aria-hidden="true">Файлы</GroupLabel>
            <GroupActions>
              <MelodyImport
                compact
                showLabel
                detailsTarget={actionDetails}
                onBeforeOpen={() => {
                  stopPlayback();
                  setEditorOpen(true);
                }}
              />

              {(!!melody.notes.length || guitar.hasTake) && !isRecording && (
                <MelodyExport
                  compact
                  showLabel
                  detailsTarget={actionDetails}
                  key={`export-${melody.firstStart}`}
                  melody={melody}
                  audioRecording={guitar}
                />
              )}
              {!!melody.notes.length && !isRecording && (
                <MelodyActionButton
                  $withLabel
                  type="button"
                  aria-label="Копировать мелодию"
                  title="Скопировать мелодию"
                  onClick={() => {
                    navigator.clipboard.writeText(
                      JSON.stringify(dissoc('firstStart', melody)),
                    );
                  }}
                >
                  <MelodyActionIcon action="copy" />
                  Копировать
                </MelodyActionButton>
              )}
            </GroupActions>
          </ControlGroup>
        </RecordingBar>
        {!!melody.notes.length && !isRecording && (
          <RecordingPlaybackPosition melody={melody} playback={playback} />
        )}
        <SandboxViews />
      </SandboxToolbar>

      <ActionDetails ref={setActionDetails} />
      <MelodyScaleOptimization
        melody={melody}
        recording
        onStop={stopPlayback}
      />

      {editorOpen && !isRecording && (
        <RecordingEditor
          key={recordingVersion}
          melody={melody}
          onStop={stopPlayback}
          onPlay={playback.play}
          isPlaying={isPlaying}
          isPaused={playback.isPaused}
          isAudition={playback.isAudition}
          onPause={playback.pause}
          onResume={playback.resume}
          onSeek={playback.seek}
          position={playback.position}
          timelinePlaying={playback.timelinePlaying}
          onChange={(notes, bpm) => {
            batch(() => {
              dispatch(notesActions.editRecording({ notes, bpm }));
              dispatch(settingsActions.setBpm(bpm));
            });
          }}
        />
      )}

      <LiveAudioRecognition />
      <ScoreSection aria-label="Ноты и табулатура">
        <Outlet context={isRecording ? undefined : playback} />
      </ScoreSection>

      {!flyingNotes && <SandboxInstrument />}
    </SandboxWrapper>
  );
};

const SandboxWrapper = styled(PageWrapper)`
  padding-top: 0;
`;

const SandboxToolbar = styled.div`
  position: sticky;
  top: var(--app-header-height, 0px);
  z-index: 10;
  display: grid;
  gap: 4px;
  padding: 8px 0;
  margin-bottom: 12px;
  background: ${p => p.theme.background};
  border-bottom: 1px solid ${p => p.theme.border};

  ${MelodyActionButton} {
    height: 32px;
    min-height: 32px;
    gap: 6px;
    padding: 0 8px;
    font-size: 12px;
    border-radius: 6px;

    svg {
      width: 16px;
      height: 16px;
    }

    @media (pointer: coarse) {
      height: 44px;
      min-height: 44px;
    }
  }
`;

const RecordingBar = styled.div`
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  overflow-x: auto;
  padding: 4px;
`;

const ControlGroup = styled.div`
  display: flex;
  flex-shrink: 0;
  align-items: center;
  min-width: 0;
  gap: 6px;

  & + & {
    padding-left: 12px;
    border-left: 1px solid ${p => p.theme.border};
  }
`;

const GroupLabel = styled.span`
  color: ${p => p.theme.textSecondary};
  font-size: 10px;
`;

const GroupActions = styled.div`
  display: flex;
  align-items: center;
  gap: 4px;
`;

const RecordButton = styled(MelodyActionButton)`
  background: ${p => p.theme.primary};
  border-color: ${p => p.theme.primary};
  color: ${p => p.theme.onPrimary};
`;

const ActionDetails = styled.div`
  display: grid;
  gap: 12px;
  margin-bottom: 20px;
  &:empty {
    display: none;
  }
`;

const ScoreSection = styled.section`
  min-height: 240px;
  min-width: 0;
  margin-bottom: 20px;
  overflow-x: auto;
  @media (max-width: 700px) {
    min-height: 200px;
  }
`;
