import type { StringInstrumentType } from 'app/components/Tablature/types';

export const scoreFormats = {
  pdf: { label: 'ноты', suffix: 'staff', instrument: undefined },
  'pdf-guitar': {
    label: 'табы для гитары',
    suffix: 'guitar-tabs',
    instrument: 'guitar',
  },
  'pdf-guitar-drop-d': {
    label: 'табы для гитары Drop D',
    suffix: 'guitar-drop-d-tabs',
    instrument: 'guitarDropD',
  },
  'pdf-bass': {
    label: 'табы для баса',
    suffix: 'bass-tabs',
    instrument: 'bass',
  },
  'pdf-ukulele': {
    label: 'табы для укулеле',
    suffix: 'ukulele-tabs',
    instrument: 'ukulele',
  },
} as const;

export type ScoreExportFormat = keyof typeof scoreFormats;

export const isScoreFormat = (format: string): format is ScoreExportFormat =>
  Object.prototype.hasOwnProperty.call(scoreFormats, format);

export const getScoreInstrument = (
  format: ScoreExportFormat,
): StringInstrumentType | undefined => scoreFormats[format].instrument;
