import { useState } from 'react';
import styled from 'styled-components';

import {
  EffectPreset,
  builtInEffectPresets,
  canAddPresetPedal,
  effectPresetCategories,
  filterEffectPresets,
  togglePresetPedal,
} from 'app/services/EffectsService/presets';
import {
  InstrumentEffects,
  MAX_PEDALS,
  PresetPedal,
  effectDefinitions,
  effectNames,
} from 'app/services/EffectsService/settings';

import { EffectPedalCard } from './EffectPedalCard';

export const PresetPedalboard = ({
  settings,
  onChange,
  customPresets,
}: {
  settings: InstrumentEffects;
  onChange: (settings: InstrumentEffects) => void;
  customPresets: EffectPreset[];
}) => {
  const pedals = settings.pedals ?? [];
  const [query, setQuery] = useState('');
  const [category, setCategory] = useState('all');
  const [page, setPage] = useState(0);
  const [editing, setEditing] = useState('');
  const [stageIndex, setStageIndex] = useState(0);
  const [catalogOpen, setCatalogOpen] = useState(pedals.length === 0);
  const results = filterEffectPresets(
    [...builtInEffectPresets, ...customPresets],
    query,
    category,
  );
  const pageSize = 12;
  const pages = Math.max(1, Math.ceil(results.length / pageSize));
  const currentPage = Math.min(page, pages - 1);
  const replace = (next: PresetPedal[]) =>
    onChange({ ...settings, pedals: next });
  const edited = pedals.find(item => item.id === editing);
  const stage = edited?.stages[stageIndex];
  const move = (index: number, offset: number) => {
    const next = [...pedals];
    [next[index], next[index + offset]] = [next[index + offset], next[index]];
    replace(next);
  };
  return (
    <Board aria-label="Педалборд пресетов">
      <Heading>
        <strong>Педалборд</strong>
        <span>
          {pedals.filter(item => item.enabled).length} включено ·{' '}
          {pedals.length} / {MAX_PEDALS}
        </span>
      </Heading>
      <p>
        Сигнал идёт через фейдеры, затем через педали слева направо. Нажимайте
        на любую часть педали, чтобы включать и обходить её.
      </p>
      {pedals.length > 0 ? (
        <Chain role="list" aria-label="Порядок педалей">
          {pedals.map((pedal, index) => (
            <Slot key={pedal.id} role="listitem">
              <Order>
                {index + 1} <span aria-hidden="true">→</span>
              </Order>
              <EffectPedalCard
                id={pedal.presetId}
                name={pedal.name}
                active={pedal.enabled && !settings.bypass}
                pressed={pedal.enabled}
                action={`Педаль ${index + 1}: ${pedal.name}`}
                onToggle={() =>
                  replace(
                    pedals.map(item =>
                      item.id === pedal.id
                        ? { ...item, enabled: !item.enabled }
                        : item,
                    ),
                  )
                }
              />
              <SlotActions>
                <button
                  type="button"
                  aria-label={`Переместить ${pedal.name} влево`}
                  disabled={index === 0}
                  onClick={() => move(index, -1)}
                >
                  ←
                </button>
                <button
                  type="button"
                  aria-label={`Переместить ${pedal.name} вправо`}
                  disabled={index === pedals.length - 1}
                  onClick={() => move(index, 1)}
                >
                  →
                </button>
                <button
                  type="button"
                  onClick={() => {
                    setEditing(editing === pedal.id ? '' : pedal.id);
                    setStageIndex(0);
                  }}
                  aria-expanded={editing === pedal.id}
                  aria-label={`Настроить ${pedal.name}`}
                >
                  Настроить
                </button>
                <button
                  type="button"
                  aria-label={`Убрать ${pedal.name}`}
                  onClick={() =>
                    replace(pedals.filter(item => item.id !== pedal.id))
                  }
                >
                  ×
                </button>
              </SlotActions>
            </Slot>
          ))}
        </Chain>
      ) : (
        <Empty>
          Добавьте первую педаль из каталога. Фейдеры ниже продолжают работать
          независимо.
        </Empty>
      )}
      {edited && stage && (
        <Editor aria-label={`Настройки педали ${edited.name}`}>
          <Heading>
            <strong>{edited.name}</strong>
            <button type="button" onClick={() => setEditing('')}>
              Закрыть настройки педали
            </button>
          </Heading>
          {edited.stages.length > 1 && (
            <label>
              Секция сохранённой цепочки
              <select
                value={stageIndex}
                onChange={event => setStageIndex(Number(event.target.value))}
              >
                {edited.stages.map((_, index) => (
                  <option key={index} value={index}>
                    Секция {index + 1}
                  </option>
                ))}
              </select>
            </label>
          )}
          <Controls>
            {effectNames.map(name => {
              const definition = effectDefinitions[name];
              const effect = stage[name];
              const update = (key: string, value: number | boolean) =>
                replace(
                  pedals.map(pedal =>
                    pedal.id !== edited.id
                      ? pedal
                      : {
                          ...pedal,
                          stages: pedal.stages.map((item, index) =>
                            index !== stageIndex
                              ? item
                              : {
                                  ...item,
                                  [name]: {
                                    ...effect,
                                    [key]: value,
                                    enabled:
                                      key === 'enabled' ? Boolean(value) : true,
                                  },
                                },
                          ),
                        },
                  ),
                );
              return (
                <fieldset key={name}>
                  <legend>
                    <label>
                      <input
                        type="checkbox"
                        checked={effect.enabled}
                        onChange={event =>
                          update('enabled', event.target.checked)
                        }
                      />
                      {definition.title}
                    </label>
                  </legend>
                  {definition.controls.map(control => (
                    <label key={control.key}>
                      {control.label}:{' '}
                      {
                        (effect as unknown as Record<string, number>)[
                          control.key
                        ]
                      }{' '}
                      {control.unit}
                      <input
                        type="range"
                        data-instrument-control="true"
                        aria-label={`Педаль: ${control.label}`}
                        min={control.min}
                        max={control.max}
                        step={control.step}
                        value={
                          (effect as unknown as Record<string, number>)[
                            control.key
                          ]
                        }
                        onPointerUp={event => event.currentTarget.blur()}
                        onPointerCancel={event => event.currentTarget.blur()}
                        onChange={event =>
                          update(control.key, Number(event.target.value))
                        }
                      />
                    </label>
                  ))}
                </fieldset>
              );
            })}
          </Controls>
        </Editor>
      )}
      <details
        open={catalogOpen}
        onToggle={event => setCatalogOpen(event.currentTarget.open)}
      >
        <summary>
          Каталог педалей · {builtInEffectPresets.length} пресетов
        </summary>
        <Filters>
          <label>
            Поиск педалей
            <input
              type="search"
              value={query}
              placeholder="Фанк, chorus, бас, эмбиент…"
              onChange={event => {
                setQuery(event.target.value);
                setPage(0);
              }}
            />
          </label>
          <label>
            Категория педалей
            <select
              value={category}
              onChange={event => {
                setCategory(event.target.value);
                setPage(0);
              }}
            >
              <option value="all">Все категории</option>
              {effectPresetCategories.map(item => (
                <option key={item.id} value={item.id}>
                  {item.name}
                </option>
              ))}
              <option value="custom">Мои пресеты</option>
            </select>
          </label>
        </Filters>
        <p role="status" aria-label="Результаты поиска педалей">
          Найдено: {results.length}
          {settings.bypass ? ' · Общий обход включён' : ''}
        </p>
        {results.length === 0 && (
          <Empty>Педали не найдены. Измените запрос или категорию.</Empty>
        )}
        <Grid>
          {results
            .slice(currentPage * pageSize, (currentPage + 1) * pageSize)
            .map(preset => {
              const existing = pedals.find(
                pedal => pedal.presetId === preset.id,
              );
              return (
                <CatalogItem key={preset.id}>
                  <EffectPedalCard
                    id={preset.id}
                    name={preset.name}
                    description={preset.description}
                    active={!!existing?.enabled && !settings.bypass}
                    pressed={!!existing?.enabled}
                    disabled={!existing && !canAddPresetPedal(settings, preset)}
                    action={`${existing ? 'Переключить' : 'Добавить'} педаль ${
                      preset.name
                    }`}
                    onToggle={() =>
                      onChange(togglePresetPedal(settings, preset))
                    }
                  />
                  <Description>
                    {preset.description ?? 'Сохранённая вами обработка.'}
                  </Description>
                </CatalogItem>
              );
            })}
        </Grid>
        <Pagination>
          <button
            type="button"
            disabled={currentPage === 0}
            onClick={() => setPage(currentPage - 1)}
          >
            Предыдущие педали
          </button>
          <span>
            {currentPage + 1} / {pages}
          </span>
          <button
            type="button"
            disabled={currentPage + 1 >= pages}
            onClick={() => setPage(currentPage + 1)}
          >
            Следующие педали
          </button>
        </Pagination>
        <p>
          До {MAX_PEDALS} педалей и 24 секций обработки в цепочке. Отключённые
          педали сохраняют свои настройки.
        </p>
      </details>
    </Board>
  );
};

const Board = styled.section`
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid ${p => p.theme.border};
  p {
    color: ${p => p.theme.textSecondary};
    line-height: 1.5;
  }
  summary {
    cursor: pointer;
    padding: 12px 0;
    font-weight: 600;
  }
`;
const Heading = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  span {
    color: ${p => p.theme.textSecondary};
  }
`;
const Chain = styled.div`
  display: flex;
  gap: 20px;
  overflow-x: auto;
  padding: 6px 6px 12px;
  overscroll-behavior-x: contain;
`;
const Slot = styled.div`
  flex: 0 0 174px;
  min-width: 0;
`;
const Order = styled.div`
  display: flex;
  justify-content: space-between;
  margin-bottom: 6px;
  color: ${p => p.theme.textSecondary};
  font: 11px monospace;
`;
const SlotActions = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 10px;
  button {
    padding: 4px 8px;
  }
`;
const Empty = styled.p`
  padding: 16px;
  border: 1px dashed ${p => p.theme.border};
  border-radius: 8px;
`;
const Filters = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin: 4px 0 12px;
  label {
    flex: 1 1 220px;
    min-width: 0;
  }
`;
const Grid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(136px, 1fr));
  gap: 22px 18px;
  padding: 5px;
`;
const CatalogItem = styled.div`
  min-width: 0;
`;
const Description = styled.p`
  margin: 10px 0 0;
  font-size: 11px;
  line-height: 1.5;
`;
const Pagination = styled.div`
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  margin-top: 16px;
`;
const Editor = styled.section`
  margin: 12px 0;
  padding: 12px;
  background: ${p => p.theme.surface};
  border: 1px solid ${p => p.theme.border};
  border-radius: 8px;
`;
const Controls = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(220px, 100%), 1fr));
  gap: 12px;
  margin-top: 12px;
  fieldset {
    min-width: 0;
    border: 1px solid ${p => p.theme.border};
    border-radius: 6px;
  }
  label {
    margin: 8px 0;
  }
  input[type='checkbox'] {
    width: auto;
    min-height: 0;
  }
  legend label {
    display: inline-flex;
    flex-direction: row;
    align-items: center;
  }
`;
