import { NoteInMelody } from './types';

export const DEFAULT_BPM = 90;
export const LEGACY_NOTE_DURATION = 100;

// Old melodies contain missing and zero-length notes. Keep them audible without
// changing the original recording. New recordings always close with duration > 0.
export const getNoteDuration = ({ duration }: NoteInMelody) =>
  duration !== undefined && Number.isFinite(duration) && duration > 0
    ? duration
    : LEGACY_NOTE_DURATION;
