import styled from 'styled-components';

import { InstrumentEffects } from 'app/services/EffectsService/settings';

export const WahControl = ({
  settings,
  onChange,
}: {
  settings: InstrumentEffects;
  onChange: (settings: InstrumentEffects) => void;
}) => (
  <Control>
    Управление
    <select
      aria-label="Управление квакушкой"
      data-instrument-control="true"
      value={settings.wahMode ?? 'auto'}
      onChange={event => {
        const hasWah =
          settings.wah.enabled ||
          settings.pedals?.some(
            pedal =>
              pedal.enabled && pedal.stages.some(stage => stage.wah.enabled),
          );
        onChange({
          ...settings,
          wahMode: event.target.value === 'cursor' ? 'cursor' : 'auto',
          wah: { ...settings.wah, enabled: settings.wah.enabled || !hasWah },
        });
        event.currentTarget.blur();
      }}
      title="Курсор: удерживайте ноту и двигайте вправо или вверх, чтобы открыть фильтр. Жест управляет квакушкой вместо бенда. Автоматически: работают скорость и автокачание."
    >
      <option value="auto">Автоматически</option>
      <option value="cursor">Курсором</option>
    </select>
  </Control>
);

const Control = styled.label`
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 0 0 8px;
  font-size: 11px;
  select {
    width: 100%;
    min-width: 0;
  }
`;
